// Mock data types and initial data store
export interface User {
  id: string;
  email: string;
  fullName: string;
  password: string;
  role: 'user' | 'admin';
  age?: string;
  guardianName?: string;
  guardianEmail?: string;
  createdAt: string;
}

export interface Report {
  id: string;
  caseId: string;
  userId: string;
  reporterName: string;
  incidentType: string;
  platform: string;
  description: string;
  status: 'pending' | 'under_review' | 'need_more_info' | 'closed';
  priority: 'low' | 'medium' | 'high';
  evidence: string[];
  createdAt: string;
  submittedAt: string;
  assignedTo?: string;
  messages: Message[];
  internalNotes: InternalNote[];
}

export interface Message {
  id: string;
  sender: 'user' | 'admin';
  senderName: string;
  content: string;
  createdAt: string;
  isTemplate?: boolean;
}

export interface InternalNote {
  id: string;
  adminName: string;
  content: string;
  createdAt: string;
}

export interface Evidence {
  id: string;
  reportId: string;
  fileName: string;
  fileType: string;
  fileSize: number;
  uploadedAt: string;
  uploadedBy: string;
  isSensitive: boolean;
  accessedBy: string[];
}

export interface Admin {
  id: string;
  email: string;
  fullName: string;
  password: string;
  role: 'admin';
  notificationsEnabled: boolean;
  createdAt: string;
}

