// Local storage keys
const USERS_KEY = 'trustline_users';
const REPORTS_KEY = 'trustline_reports';
const EVIDENCE_KEY = 'trustline_evidence';
const CURRENT_USER_KEY = 'trustline_current_user';
const CURRENT_ROLE_KEY = 'trustline_current_role';

// Initialize localStorage with mock data
export function initializeMockData() {
  if (typeof window === 'undefined') return;

  if (!localStorage.getItem(USERS_KEY)) {
    localStorage.setItem(USERS_KEY, JSON.stringify(mockUsers));
  }
  if (!localStorage.getItem(REPORTS_KEY)) {
    localStorage.setItem(REPORTS_KEY, JSON.stringify(mockReports));
  }
  if (!localStorage.getItem(EVIDENCE_KEY)) {
    localStorage.setItem(EVIDENCE_KEY, JSON.stringify(mockEvidence));
  }
}

// User operations
export function getUsers(): User[] {
  if (typeof window === 'undefined') return mockUsers;
  const data = localStorage.getItem(USERS_KEY);
  return data ? JSON.parse(data) : mockUsers;
}

export function addUser(user: User) {
  if (typeof window === 'undefined') return;
  const users = getUsers();
  users.push(user);
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
}

export function getUserByEmail(email: string): User | undefined {
  return getUsers().find(u => u.email === email);
}

export function setCurrentUser(userId: string, role: 'user' | 'admin') {
  if (typeof window === 'undefined') return;
  localStorage.setItem(CURRENT_USER_KEY, userId);
  localStorage.setItem(CURRENT_ROLE_KEY, role);
}

export function getCurrentUser(): { userId: string; role: 'user' | 'admin' } | null {
  if (typeof window === 'undefined') return null;
  const userId = localStorage.getItem(CURRENT_USER_KEY);
  const role = (localStorage.getItem(CURRENT_ROLE_KEY) as 'user' | 'admin') || 'user';
  return userId ? { userId, role } : null;
}

export function clearCurrentUser() {
  if (typeof window === 'undefined') return;
  localStorage.removeItem(CURRENT_USER_KEY);
  localStorage.removeItem(CURRENT_ROLE_KEY);
}

export function getUserById(id: string): User | undefined {
  return getUsers().find(u => u.id === id);
}

// Report operations
export function getReports(): Report[] {
  if (typeof window === 'undefined') return mockReports;
  const data = localStorage.getItem(REPORTS_KEY);
  return data ? JSON.parse(data) : mockReports;
}

export function getReportById(id: string): Report | undefined {
  return getReports().find(r => r.id === id);
}

export function getReportByCaseId(caseId: string): Report | undefined {
  return getReports().find(r => r.caseId === caseId);
}

export function getUserReports(userId: string): Report[] {
  return getReports().filter(r => r.userId === userId);
}

export function addReport(report: Report) {
  if (typeof window === 'undefined') return;
  const reports = getReports();
  reports.push(report);
  localStorage.setItem(REPORTS_KEY, JSON.stringify(reports));
}

export function updateReport(reportId: string, updates: Partial<Report>) {
  if (typeof window === 'undefined') return;
  const reports = getReports();
  const index = reports.findIndex(r => r.id === reportId);
  if (index !== -1) {
    reports[index] = { ...reports[index], ...updates };
    localStorage.setItem(REPORTS_KEY, JSON.stringify(reports));
  }
}

export function generateCaseId(): string {
  const random = Math.floor(Math.random() * 900000) + 100000;
  return `TL-2026-${random}`;
}

// Evidence operations
export function getEvidence(): Evidence[] {
  if (typeof window === 'undefined') return mockEvidence;
  const data = localStorage.getItem(EVIDENCE_KEY);
  return data ? JSON.parse(data) : mockEvidence;
}

export function getEvidenceByReportId(reportId: string): Evidence[] {
  return getEvidence().filter(e => e.reportId === reportId);
}

export function addEvidence(evidence: Evidence) {
  if (typeof window === 'undefined') return;
  const allEvidence = getEvidence();
  allEvidence.push(evidence);
  localStorage.setItem(EVIDENCE_KEY, JSON.stringify(allEvidence));
}

export function updateEvidence(evidenceId: string, updates: Partial<Evidence>) {
  if (typeof window === 'undefined') return;
  const allEvidence = getEvidence();
  const index = allEvidence.findIndex(e => e.id === evidenceId);
  if (index !== -1) {
    allEvidence[index] = { ...allEvidence[index], ...updates };
    localStorage.setItem(EVIDENCE_KEY, JSON.stringify(allEvidence));
  }
}
